//! Kern pairs and ligatures of the Base-14 text fonts RushTeX typesets with.
//!
//! Generated from the Adobe Core14 AFM files (freely redistributable) by a generator script
//! kept outside the repository; do not edit by hand. Glyphs are addressed by their
//! WinAnsiEncoding code. `fi`/`fl`, absent from WinAnsi, live in the undefined slots
//! [`WINANSI_FI`]/[`WINANSI_FL`], which the PDF backend maps with a `/Differences` array.
//! Kerns (AFM `KPX`) are in 1/10000 em; ligatures are the AFM `L` entries plus TeX's
//! standard text ligatures (`--`, `---`, two backquotes, two quotes, `!` + backquote,
//! `?` + backquote), exactly as fontinst builds them into pdfTeX's `ptmr7t`/`phvr7t`.

#![forbid(unsafe_code)]

use crate::backend::backend_ligkern::LigKernTable;

/// WinAnsi slot carrying the `fi` ligature.
pub const WINANSI_FI: u8 = 0x81;
/// WinAnsi slot carrying the `fl` ligature.
pub const WINANSI_FL: u8 = 0x8D;

